class DeslocamentoModelo {
  static Deslocamento? fromMap(Map<String, dynamic> map) {
    final distancia = map['distanciaMetros'] as num?;
    final duracao = map['duracaoSegundos'] as num?;
    if (distancia == null || duracao == null) return null;
    final polilinha = map['polilinha'] as String?;
    return Deslocamento(
      distanciaMetros: distancia.toInt(),
      duracaoSegundos: duracao.toInt(),
      rota: polilinha == null ? const [] : decodificar(polilinha),
    );
  }

  static Map<String, dynamic> toMap(Deslocamento deslocamento) {
    return {
      'distanciaMetros': deslocamento.distanciaMetros,
      'duracaoSegundos': deslocamento.duracaoSegundos,
      if (deslocamento.rota.isNotEmpty)
        'polilinha': codificar(deslocamento.rota),
    };
  }

  static List<Coordenada> decodificar(String polilinha) {
    final pontos = <Coordenada>[];
    var indice = 0;
    var latitude = 0;
    var longitude = 0;
    int proximo() {
      var resultado = 0;
      var deslocamento = 0;
      int byte;
      do {
        byte = polilinha.codeUnitAt(indice++) - 63;
        resultado |= (byte & 0x1F) << deslocamento;
        deslocamento += 5;
      } while (byte >= 0x20);
      return (resultado & 1) != 0 ? ~(resultado >> 1) : resultado >> 1;
    }

    try {
      while (indice < polilinha.length) {
        latitude += proximo();
        longitude += proximo();
        pontos.add(Coordenada(latitude / 1e5, longitude / 1e5));
      }
    } on RangeError {
      return [];
    }
    return pontos;
  }

  static String codificar(List<Coordenada> rota) {
    final texto = StringBuffer();
    void escrever(int valor) {
      var restante = valor < 0 ? ~(valor << 1) : valor << 1;
      while (restante >= 0x20) {
        texto.writeCharCode((0x20 | (restante & 0x1F)) + 63);
        restante >>= 5;
      }
      texto.writeCharCode(restante + 63);
    }

    var latitude = 0;
    var longitude = 0;
    for (final ponto in rota) {
      final proximaLatitude = (ponto.latitude * 1e5).round();
      final proximaLongitude = (ponto.longitude * 1e5).round();
      escrever(proximaLatitude - latitude);
      escrever(proximaLongitude - longitude);
      latitude = proximaLatitude;
      longitude = proximaLongitude;
    }
    return texto.toString();
  }
}

