class ClienteRepositorioDados implements ClienteRepositorio {
  final ClienteFonte _fonte;

  ClienteRepositorioDados(this._fonte);

  @override
  Future<Cliente?> buscar(String uid) async {
    final dados = await _fonte.buscar(uid);
    if (dados == null || dados['perfil'] != 'cliente') return null;
    return ClienteModelo.fromMap(uid, dados);
  }

  @override
  Stream<List<Cliente>> observarClientes() {
    return _fonte.observarClientes().map(
      (documentos) => documentos.entries
          .map(
            (documento) =>
                ClienteModelo.fromMap(documento.key, documento.value),
          )
          .toList(),
    );
  }

  @override
  Future<bool> cpfJaCadastrado(String cpf) => _fonte.cpfJaCadastrado(cpf);

  @override
  Future<void> salvar(Cliente cliente) {
    return _fonte.salvar(cliente.id, cliente.cpf, ClienteModelo.toMap(cliente));
