      nome: nome,
      telefone: telefone,
      cpf: cpf,
      dataNascimento: dataNascimento,
      endereco: endereco,
      completandoCadastro: completandoCadastro,
      email: email,
      senha: senha,
    );
    if (erros.isNotEmpty) throw FalhaValidacao(erros);

    final cpfNumeros = _somenteNumeros(cpf);
    // RN03: o CPF não pode estar em uso por outra conta.
    if (await _clientes.cpfJaCadastrado(cpfNumeros)) {
      throw const FalhaValidacao({
        'cpf': 'Este CPF já está cadastrado.',
      }, 'Este CPF já está cadastrado.');
    }
    final uid = completandoCadastro
        ? _autenticacao.uidAtual!
        : await _autenticacao.criarConta(email.trim(), senha);
    await _clientes.salvar(
      Cliente(
        id: uid,
        nome: nome.trim(),
        telefone: telefone.trim(),
        cpf: cpfNumeros,
        dataNascimento: dataNascimento!,
        endereco: endereco,
        email: completandoCadastro
            ? _autenticacao.emailAtual ?? ''
            : email.trim(),
      ),
    );
  }

  Map<String, String> validar({
    required String nome,
    required String telefone,
    required String cpf,
    required DateTime? dataNascimento,
    required Endereco endereco,
    required bool completandoCadastro,
    String email = '',
    String senha = '',
  }) {
    final erros = <String, String>{};
    if (nome.trim().isEmpty) erros['nome'] = 'Informe o nome.';
    if (_somenteNumeros(telefone).length != 11) {
      erros['telefone'] = 'Informe o celular com DDD, 11 dígitos.';
    }
    // RN03: CPF válido, conferido pelos dois dígitos verificadores.
    if (!_cpfValido(_somenteNumeros(cpf))) erros['cpf'] = 'CPF inválido';
    if (dataNascimento == null) {
      erros['dataNascimento'] = 'Informe a data de nascimento.';
    } else if (dataNascimento.isAfter(DateTime.now())) {
      erros['dataNascimento'] = 'Data de nascimento inválida.';
    }

    erros.addAll(endereco.errosDePreenchimento);

    if (!completandoCadastro) {
      if (!email.trim().contains('@')) {
        erros['email'] = 'Informe um e-mail válido.';
      }
      if (senha.length < 6) {
        erros['senha'] = 'A senha deve ter no mínimo seis caracteres.';
      }
    }
    return erros;
  }

  String _somenteNumeros(String texto) => texto.replaceAll(RegExp(r'\D'), '');

  bool _cpfValido(String cpf) {
    if (!RegExp(r'^\d{11}$').hasMatch(cpf)) return false;
    if (RegExp(r'^(\d)\1{10}$').hasMatch(cpf)) return false;
    final digitos = cpf.split('').map(int.parse).toList();
    int verificador(int tamanho) {
      var soma = 0;
      for (var i = 0; i < tamanho; i++) {
        soma += digitos[i] * (tamanho + 1 - i);
      }
      final resto = (soma * 10) % 11;
      return resto == 10 ? 0 : resto;
    }

    return verificador(9) == digitos[9] && verificador(10) == digitos[10];
  }
