class EnviarPedido {
  final AutenticacaoRepositorio _autenticacao;
  final ClienteRepositorio _clientes;
  final ProdutoRepositorio _produtos;
  final PedidoRepositorio _pedidos;

  EnviarPedido(
    this._autenticacao,
    this._clientes,
    this._produtos,
    this._pedidos,
  );

  String? validar(List<ItemCarrinho> itens) {
    return itens.isEmpty ? 'O carrinho está vazio.' : null;
  }

  Future<String> executar(List<ItemCarrinho> itens) async {
    final mensagem = validar(itens);
    if (mensagem != null) throw FalhaServico(mensagem);

    final uid = _autenticacao.uidAtual!;
    final cliente = await _clientes.buscar(uid);
    if (cliente == null || !cliente.endereco.completo) {
      throw const FalhaServico(
        'Complete o seu endereço no cadastro antes de fazer o pedido.',
      );
    }

    // RN01: confere de novo, porque o estoque pode ter mudado.
    final estoqueAtual = {
      for (final produto in await _produtos.buscarProdutos())
        produto.id: produto,
    };
    final itensPedido = <ItemPedido>[];
    for (final item in itens) {
      final atual = estoqueAtual[item.produto.id];
      if (atual == null || item.quantidade > atual.quantidadeEstoque) {
        throw FalhaServico(
          'O estoque de ${item.produto.nome} mudou: há apenas '
          '${atual?.quantidadeEstoque ?? 0}.',
        );
      }
      itensPedido.add(
        ItemPedido(
          produtoId: atual.id,
          nomeProduto: atual.nome,
          precoUnitario: atual.preco,
          quantidadePedida: item.quantidade,
        ),
      );
    }

    return _pedidos.criar(
      Pedido(
        id: '',
        clienteId: uid,
        clienteNome: cliente.nome,
        clienteTelefone: cliente.telefone,
        endereco: cliente.endereco,
        itens: itensPedido,
        situacao: SituacaoPedido.aguardando,
        dataCriacao: DateTime.now(),
      ),
    );
  }
}

