class FinalizarEntrega {
  final PedidoRepositorio _pedidos;
  final ProdutoRepositorio _produtos;

  FinalizarEntrega(this._pedidos, this._produtos);

  String? validar(Pedido? pedido, Map<String, int?> quantidades) {
    if (pedido == null || pedido.situacao != SituacaoPedido.aceito) {
      return 'Somente pedidos aceitos podem ser finalizados.';
    }
    if (quantidades.values.any((valor) => valor == null || valor < 0)) {
      return 'As quantidades entregues não podem ser negativas.';
    }
    return null;
  }

  Future<void> executar(Pedido? pedido, Map<String, int?> quantidades) async {
    final problema = validar(pedido, quantidades);
    if (problema != null) throw FalhaServico(problema);

    // RN04: a baixa usa as quantidades entregues, mesmo acima das pedidas.
    final estoque = {
      for (final produto in await _produtos.buscarProdutos())
        produto.id: produto.quantidadeEstoque,
    };
    for (final item in pedido!.itens) {
      final disponivel = estoque[item.produtoId] ?? 0;
      if (quantidades[item.produtoId]! > disponivel) {
        throw FalhaServico(
          'Estoque insuficiente de ${item.nomeProduto}: '
          'há apenas $disponivel.',
        );
      }
    }
    await _pedidos.finalizarEntrega(
      pedido,
      quantidades.map((id, valor) => MapEntry(id, valor!)),
    );
  }
}

