    SituacaoPedido.aguardando => 0,
    SituacaoPedido.aceito => 1,
    SituacaoPedido.entregue || SituacaoPedido.recusado => 2,
  };

  int _comparar(Pedido a, Pedido b) {
    final grupoA = _grupo(a.situacao);
