class ResumirPedidosDoCliente {
  ResumoPedidos executar(List<Pedido> pedidos) {
    final entregues = pedidos.where(
      (pedido) => pedido.situacao == SituacaoPedido.entregue,
    );
    DateTime? ultimoPedido;
    for (final pedido in pedidos) {
      if (ultimoPedido == null || pedido.dataCriacao.isAfter(ultimoPedido)) {
        ultimoPedido = pedido.dataCriacao;
      }
    }
    return (
      total: pedidos.length,
      entregues: entregues.length,
      totalGasto: entregues.fold(
        0,
        (total, pedido) => total + pedido.valorFinal,
      ),
      ultimoPedido: ultimoPedido,
    );
  }
}

