    Produto? produto,
    required String nome,
    required double? preco,
    required int? quantidadeInicial,
  }) {
    if (nome.trim().isEmpty) return 'Informe o nome do produto.';
    if (preco == null || preco <= 0) {
      return 'O preço deve ser maior que zero.';
    }
    if (produto == null &&
        (quantidadeInicial == null || quantidadeInicial < 0)) {
      return 'A quantidade inicial não pode ser negativa.';
    }
    return null;
  }

  Future<void> executar({
    Produto? produto,
    required String nome,
    required double? preco,
    required int? quantidadeInicial,
  }) async {
    final problema = validar(
      produto: produto,
      nome: nome,
      preco: preco,
      quantidadeInicial: quantidadeInicial,
    );
    if (problema != null) throw FalhaServico(problema);

    if (produto == null) {
      await _produtos.criar(
        Produto(
          id: '',
          nome: nome.trim(),
          preco: preco!,
          quantidadeEstoque: quantidadeInicial!,
        ),
      );
    } else {
      await _produtos.editar(produto.id, nome: nome.trim(), preco: preco!);
    }
  }
