class ClienteFirestore implements ClienteFonte {
  final FirebaseFirestore _firestore;

  ClienteFirestore(this._firestore);

  @override
  Future<Map<String, dynamic>?> buscar(String uid) async {
    try {
      final documento = await _firestore.collection('usuarios').doc(uid).get();
      return documento.data();
    } on FirebaseException {
      throw const FalhaConexao();
    }
  }

  @override
  Stream<Map<String, Map<String, dynamic>>> observarClientes() {
    return _firestore
        .collection('usuarios')
        .where('perfil', isEqualTo: 'cliente')
        .snapshots()
        .map(
          (consulta) => {
            for (final documento in consulta.docs)
              documento.id: documento.data(),
          },
        );
  }

  @override
  Future<bool> cpfJaCadastrado(String cpf) async {
    try {
      final documento = await _firestore.collection('cpfs').doc(cpf).get();
      return documento.exists;
    } on FirebaseException {
      throw const FalhaConexao();
    }
  }

  @override
  Future<void> salvar(
    String uid,
    String cpf,
    Map<String, dynamic> dados,
  ) async {
    try {
      final lote = _firestore.batch();
      lote.set(_firestore.collection('usuarios').doc(uid), dados);
      lote.set(_firestore.collection('cpfs').doc(cpf), {'uid': uid});
      await lote.commit();
    } on FirebaseException {
      throw const FalhaConexao();
    }
  }
}

