class PedidoFirestore implements PedidoFonte {
  final FirebaseFirestore _firestore;

  PedidoFirestore(this._firestore);

  CollectionReference<Map<String, dynamic>> get _pedidos =>
      _firestore.collection('pedidos');

  CollectionReference<Map<String, dynamic>> get _produtos =>
      _firestore.collection('produtos');

  @override
  Future<String> criar(Map<String, dynamic> dados) async {
    try {
      final documento = await _pedidos.add({
        ...dados.map(
          (chave, valor) => MapEntry(
            chave,
            valor is DateTime ? Timestamp.fromDate(valor) : valor,
          ),
        ),
        'dataCriacao': FieldValue.serverTimestamp(),
      });
      return documento.id;
    } on FirebaseException {
      throw const FalhaConexao();
    }
  }

  @override
  Stream<Map<String, Map<String, dynamic>>> observarPedidosDoCliente(
    String clienteId,
  ) {
    return _pedidos
        .where('clienteId', isEqualTo: clienteId)
        .snapshots()
        .map(_documentos);
  }

  @override
  Stream<Map<String, Map<String, dynamic>>> observarTodos() {
    return _pedidos.snapshots().map(_documentos);
  }

  @override
  Stream<Map<String, dynamic>?> observarPedido(String id) {
    return _pedidos
        .doc(id)
        .snapshots()
        .map(
          (documento) => documento.exists ? _comDatas(documento.data()!) : null,
        );
  }

  @override
  Future<void> gravarDeslocamento(String id, Map<String, dynamic> dados) {
    return _atualizar(id, dados);
  }

  @override
  Future<void> aceitar(String id, int tempoEstimadoMinutos) {
    return _atualizar(id, {
      'situacao': 'aceito',
      'tempoEstimadoMinutos': tempoEstimadoMinutos,
    });
  }

  @override
  Future<void> ampliarTempo(String id, int minutos) {
    return _atualizar(id, {
      'tempoEstimadoMinutos': FieldValue.increment(minutos),
    });
  }

  @override
  Future<void> recusar(String id, String motivo) {
    return _atualizar(id, {'situacao': 'recusado', 'motivoRecusa': motivo});
  }

  @override
  Future<void> finalizarEntrega(
    String id,
    List<Map<String, dynamic>> itens,
    Map<String, int> quantidadesEntregues,
  ) async {
    int entregueDe(Map<String, dynamic> item) =>
        quantidadesEntregues[item['produtoId']] ??
        item['quantidadePedida'] as int;

    try {
      await _firestore.runTransaction((transacao) async {
        final documentoPedido = _pedidos.doc(id);
        final atual = await transacao.get(documentoPedido);
        if (atual.data()?['situacao'] != 'aceito') {
          throw const FalhaServico('Este pedido não pode mais ser finalizado.');
        }

        final estoques = <String, int>{};
        for (final item in itens) {
          final produtoId = item['produtoId'] as String;
          final nomeProduto = item['nomeProduto'] as String;
          final produto = await transacao.get(_produtos.doc(produtoId));
          if (!produto.exists) {
            throw FalhaServico('O produto $nomeProduto não existe mais.');
          }
          final estoque = (produto.data()?['quantidadeEstoque'] as num? ?? 0)
              .toInt();
          if (estoque < entregueDe(item)) {
            throw EstoqueInsuficiente(nomeProduto);
          }
          estoques[produtoId] = estoque;
        }

        final itensEntregues = <Map<String, dynamic>>[];
        for (final item in itens) {
          final produtoId = item['produtoId'] as String;
          final entregue = entregueDe(item);
          transacao.update(_produtos.doc(produtoId), {
            'quantidadeEstoque': estoques[produtoId]! - entregue,
          });
          itensEntregues.add({...item, 'quantidadeEntregue': entregue});
        }
        transacao.update(documentoPedido, {
          'situacao': 'entregue',
          'itens': itensEntregues,
          'dataEntrega': Timestamp.now(),
        });
      });
    } on FalhaServico {
      rethrow;
    } on FirebaseException {
      throw const FalhaConexao();
    }
  }

  Future<void> _atualizar(String id, Map<String, Object?> dados) async {
    try {
      await _pedidos.doc(id).update(dados);
    } on FirebaseException {
      throw const FalhaConexao();
    }
  }

  Map<String, Map<String, dynamic>> _documentos(
    QuerySnapshot<Map<String, dynamic>> consulta,
  ) {
    return {
      for (final documento in consulta.docs)
        documento.id: _comDatas(documento.data()),
    };
  }

