class ProdutoFirestore implements ProdutoFonte {
  final FirebaseFirestore _firestore;

  ProdutoFirestore(this._firestore);

  CollectionReference<Map<String, dynamic>> get _produtos =>
      _firestore.collection('produtos');

  @override
  Stream<Map<String, Map<String, dynamic>>> observarProdutos() {
    return _produtos.orderBy('nome').snapshots().map(_documentos);
  }

  @override
  Future<void> garantirProdutos(
    Map<String, Map<String, dynamic>> produtos,
  ) async {
    try {
      await _firestore.runTransaction((transacao) async {
        final faltando = <String>[];
        for (final id in produtos.keys) {
          final documento = await transacao.get(_produtos.doc(id));
          if (!documento.exists) faltando.add(id);
        }
        for (final id in faltando) {
          transacao.set(_produtos.doc(id), produtos[id]!);
        }
      });
    } on FirebaseException {
      throw const FalhaConexao();
    }
  }

  @override
  Future<Map<String, Map<String, dynamic>>> buscarProdutos() async {
    try {
      return _documentos(await _produtos.get());
    } on FirebaseException {
      throw const FalhaConexao();
    }
  }

  @override
  Future<void> criar(Map<String, dynamic> dados) async {
    try {
      await _produtos.add(dados);
    } on FirebaseException {
      throw const FalhaConexao();
    }
  }

  @override
  Future<void> editar(String id, Map<String, dynamic> dados) async {
    try {
      await _produtos.doc(id).update(dados);
    } on FirebaseException {
      throw const FalhaConexao();
    }
  }

  @override
