class AcompanhamentoViewModel extends ChangeNotifier {
  final ObservarPedidosDoCliente _observarPedidos;
  StreamSubscription<List<Pedido>>? _inscricao;

  List<Pedido> pedidos = [];
  bool carregando = true;
  String? erro;

  AcompanhamentoViewModel(this._observarPedidos);

  void iniciar() {
    _inscricao = _observarPedidos.executar().listen(
      (lista) {
        pedidos = lista;
        carregando = false;
        erro = null;
        notifyListeners();
      },
      onError: (Object _) {
        carregando = false;
        erro = const FalhaConexao().mensagem;
        notifyListeners();
      },
    );
  }

  @override
  void dispose() {
    _inscricao?.cancel();
    super.dispose();
  }
}

