class CadastroViewModel extends ChangeNotifier {
  final CadastrarCliente _cadastrarCliente;

  final bool completandoCadastro;

  bool carregando = false;
  String? erro;
  Map<String, String> errosDosCampos = {};

  CadastroViewModel(this._cadastrarCliente)
    : completandoCadastro = _cadastrarCliente.haContaLogada;

  Future<bool> cadastrar({
    required String nome,
    required String telefone,
    required String cpf,
    required DateTime? dataNascimento,
    required Endereco endereco,
    String email = '',
    String senha = '',
  }) async {
    errosDosCampos = _cadastrarCliente.validar(
      nome: nome,
      telefone: telefone,
      cpf: cpf,
      dataNascimento: dataNascimento,
      endereco: endereco,
      completandoCadastro: completandoCadastro,
      email: email,
      senha: senha,
    );
    erro = errosDosCampos.isEmpty
        ? null
        : FalhaValidacao(errosDosCampos).mensagem;
    if (errosDosCampos.isNotEmpty) {
      notifyListeners();
      return false;
    }

    carregando = true;
    notifyListeners();
    try {
      await _cadastrarCliente.executar(
        nome: nome,
        telefone: telefone,
        cpf: cpf,
        dataNascimento: dataNascimento,
        endereco: endereco,
        completandoCadastro: completandoCadastro,
        email: email,
        senha: senha,
      );
      return true;
    } on FalhaValidacao catch (e) {
      errosDosCampos = e.erros;
      erro = e.mensagem;
      return false;
    } on FalhaServico catch (e) {
      erro = e.mensagem;
      return false;
    } finally {
      carregando = false;
      notifyListeners();
    }
  }

  bool validarCampos(
    Set<String> campos, {
    required String nome,
    required String telefone,
    required String cpf,
    required DateTime? dataNascimento,
    required Endereco endereco,
    String email = '',
    String senha = '',
  }) {
    final erros = _cadastrarCliente.validar(
      nome: nome,
      telefone: telefone,
      cpf: cpf,
      dataNascimento: dataNascimento,
      endereco: endereco,
      completandoCadastro: completandoCadastro,
      email: email,
      senha: senha,
    );
    errosDosCampos = {
      for (final erro in erros.entries)
        if (campos.contains(erro.key)) erro.key: erro.value,
    };
    erro = null;
    notifyListeners();
    return errosDosCampos.isEmpty;
  }
}

