class CarrinhoViewModel extends ChangeNotifier {
  final ObservarProdutos _observarProdutos;
  final BuscarEnderecoDoCliente _buscarEndereco;
  final ValidarQuantidade _validarQuantidade;
  final EnviarPedido _enviarPedido;
  StreamSubscription<List<Produto>>? _inscricao;
  final Map<String, int> _quantidades = {};
  bool _descartado = false;

  List<Produto> produtos = [];
  Endereco? enderecoEntrega;
  bool carregando = true;
  bool enviando = false;
  String? erro;

  CarrinhoViewModel(
    this._observarProdutos,
    this._buscarEndereco,
    this._validarQuantidade,
    this._enviarPedido,
  );

  void iniciar() {
    _inscricao = _observarProdutos.executar().listen(
      (lista) {
        produtos = lista;
        carregando = false;
        notifyListeners();
      },
      onError: (Object _) {
        carregando = false;
        erro = const FalhaConexao().mensagem;
        notifyListeners();
      },
    );
    _carregarEndereco();
  }

  Future<void> _carregarEndereco() async {
    try {
      final endereco = await _buscarEndereco.executar();
      if (_descartado) return;
      enderecoEntrega = endereco;
      notifyListeners();
    } on FalhaServico {
      // RN02: o endereço é conferido de novo no envio.
    }
  }

  List<ItemCarrinho> get itens => [
    for (final produto in produtos)
      if (_quantidades.containsKey(produto.id))
        (produto: produto, quantidade: _quantidades[produto.id]!),
  ];

  int quantidadeDe(Produto produto) => _quantidades[produto.id] ?? 0;

  double get valorTotal => itens.fold(
    0,
    (total, item) => total + item.produto.preco * item.quantidade,
  );

  bool alterarQuantidade(Produto produto, int quantidade) {
    final problema = _validarQuantidade.executar(produto, quantidade);
    if (problema != null) {
      erro = problema;
      notifyListeners();
      return false;
    }
    if (quantidade <= 0) {
      _quantidades.remove(produto.id);
    } else {
      _quantidades[produto.id] = quantidade;
    }
    erro = null;
    notifyListeners();
    return true;
  }

  Future<String?> enviarPedido() async {
    final itensDoPedido = itens;
    final problema = _enviarPedido.validar(itensDoPedido);
    if (problema != null) {
      erro = problema;
      notifyListeners();
      return null;
    }

    enviando = true;
    erro = null;
    notifyListeners();
    try {
      final id = await _enviarPedido.executar(itensDoPedido);
      _quantidades.clear();
      return id;
    } on FalhaServico catch (e) {
      erro = e.mensagem;
      return null;
    } finally {
      enviando = false;
      notifyListeners();
    }
  }

  @override
  void dispose() {
    _descartado = true;
    _inscricao?.cancel();
    super.dispose();
  }
}

