    this._recusarPedido,
    this._finalizarEntrega,
  );

  void iniciar(String pedidoId) {
    _inscricao = _observarPedido
        .executar(pedidoId)
        .listen(
          (atual) {
            pedido = atual;
            carregando = false;
            notifyListeners();
            if (atual != null &&
                _calcularRotaDoPedido.precisaCalcular(atual) &&
                !_rotaSolicitada) {
              _rotaSolicitada = true;
              _calcularRota(atual);
            }
          },
          onError: (Object _) {
            carregando = false;
            erro = const FalhaConexao().mensagem;
            notifyListeners();
          },
        );
  }

  Future<void> _calcularRota(Pedido atual) async {
    calculandoRota = true;
    notifyListeners();
    try {
      await _calcularRotaDoPedido.executar(atual);
    } on FalhaServico catch (e) {
      avisoRota = e.mensagem;
    } finally {
      calculandoRota = false;
      if (!_descartado) notifyListeners();
    }
  }

  Future<bool> aceitar(String tempoTexto) async {
    final atual = pedido;
    final tempo = int.tryParse(tempoTexto.trim());
    final problema = _aceitarPedido.validar(atual, tempo);
    if (problema != null) return _falhar(problema);
    return _executar(() => _aceitarPedido.executar(atual, tempo));
  }

  Future<bool> ampliarTempo(String minutosTexto) async {
    final atual = pedido;
    final minutos = int.tryParse(minutosTexto.trim());
    final problema = _ampliarTempo.validar(atual, minutos);
    if (problema != null) return _falhar(problema);
    return _executar(() => _ampliarTempo.executar(atual, minutos));
  }

  Future<bool> recusar(String motivo) async {
    final atual = pedido;
