    if (problema != null) return _falhar(problema);
    return _executar(() => _recusarPedido.executar(atual, motivo));
  }

  Future<bool> finalizarEntrega(Map<String, String> quantidadesTexto) async {
    final atual = pedido;
    final quantidades = <String, int?>{
      for (final item in atual?.itens ?? const <ItemPedido>[])
        item.produtoId: int.tryParse(
          (quantidadesTexto[item.produtoId] ?? '${item.quantidadePedida}')
              .trim(),
        ),
    };
    final problema = _finalizarEntrega.validar(atual, quantidades);
    if (problema != null) return _falhar(problema);
    return _executar(() => _finalizarEntrega.executar(atual, quantidades));
  }

  List<Coordenada> get rota => pedido?.deslocamento?.rota ?? const [];

  void limparErro() {
    if (_descartado) return;
    erro = null;
    notifyListeners();
  }

  bool _falhar(String mensagem) {
    erro = mensagem;
    notifyListeners();
    return false;
  }

  Future<bool> _executar(Future<void> Function() acao) async {
    processando = true;
    erro = null;
    notifyListeners();
    try {
      await acao();
      return true;
    } on FalhaServico catch (e) {
      erro = e.mensagem;
      return false;
    } finally {
      processando = false;
      if (!_descartado) notifyListeners();
    }
  }

