class EstoqueViewModel extends ChangeNotifier {
  final ObservarProdutos _observarProdutos;
  final GarantirProdutosFixos _garantirProdutos;
  final SalvarProduto _salvarProduto;
  final RegistrarEntrada _registrarEntrada;
  StreamSubscription<List<Produto>>? _inscricao;
  bool _descartado = false;

  List<Produto> produtos = [];
  bool carregando = true;
  bool salvando = false;
  String? erro;

  EstoqueViewModel(
    this._observarProdutos,
    this._garantirProdutos,
    this._salvarProduto,
    this._registrarEntrada,
  );

  void iniciar() {
    _inscricao = _observarProdutos.executar().listen(
      (lista) {
        produtos = lista;
        carregando = false;
        notifyListeners();
      },
      onError: (Object _) {
        carregando = false;
        erro = const FalhaConexao().mensagem;
        notifyListeners();
      },
    );
    _garantirProdutosFixos();
  }

  Future<void> _garantirProdutosFixos() async {
    try {
      await _garantirProdutos.executar();
    } on FalhaServico catch (e) {
      if (_descartado) return;
      erro = e.mensagem;
      notifyListeners();
    }
  }

  Future<bool> salvarProduto({
    Produto? produto,
    required String nome,
    required String preco,
    String quantidadeInicial = '0',
  }) async {
    final valor = double.tryParse(preco.trim().replaceAll(',', '.'));
    final quantidade = int.tryParse(quantidadeInicial.trim());

    final problema = _salvarProduto.validar(
      produto: produto,
      nome: nome,
      preco: valor,
      quantidadeInicial: quantidade,
    );
    if (problema != null) return _falhar(problema);

    return _executar(
      () => _salvarProduto.executar(
        produto: produto,
        nome: nome,
        preco: valor,
        quantidadeInicial: quantidade,
      ),
    );
  }

  Future<bool> registrarEntrada(Produto produto, String quantidade) async {
    final recebida = int.tryParse(quantidade.trim());
    final problema = _registrarEntrada.validar(recebida);
    if (problema != null) return _falhar(problema);
    return _executar(() => _registrarEntrada.executar(produto, recebida));
  }

  void limparErro() {
    if (_descartado) return;
    erro = null;
    notifyListeners();
  }

  bool _falhar(String mensagem) {
    erro = mensagem;
    notifyListeners();
    return false;
  }

  Future<bool> _executar(Future<void> Function() acao) async {
    salvando = true;
    erro = null;
    notifyListeners();
    try {
      await acao();
      return true;
    } on FalhaServico catch (e) {
      erro = e.mensagem;
      return false;
    } finally {
      salvando = false;
      if (!_descartado) notifyListeners();
    }
  }

  @override
  void dispose() {
    _descartado = true;
    _inscricao?.cancel();
    super.dispose();
  }
}

