  StreamSubscription<List<Pedido>>? _inscricao;

  final DateTime Function() _agora;

  List<Pedido> pedidos = [];
  Set<SituacaoPedido> situacoes = {};
  PeriodoPedidos periodo = PeriodoPedidos.todos;
  String busca = '';
  bool carregando = true;
  String? erro;

  PedidosViewModel(
    this._observarPedidos,
    this._garantirProdutos,
    this._filtrarPedidos, {
    DateTime Function()? agora,
  }) : _agora = agora ?? DateTime.now;

  void iniciar() {
    _garantirProdutos.executar().onError<FalhaServico>((_, _) {});
    _inscricao = _observarPedidos.executar().listen(
      (lista) {
        pedidos = lista;
        carregando = false;
        erro = null;
        notifyListeners();
      },
      onError: (Object _) {
        carregando = false;
        erro = const FalhaConexao().mensagem;
        notifyListeners();
      },
    );
  }

  List<Pedido> get pedidosFiltrados => _filtrarPedidos.executar(
    pedidos,
    situacoes: situacoes,
    periodo: periodo,
    busca: busca,
    agora: _agora(),
  );

  int get filtrosAtivos =>
      situacoes.length + (periodo == PeriodoPedidos.todos ? 0 : 1);

  String get resumoFiltros => [
    for (final situacao in situacoes) situacao.rotulo,
    if (periodo != PeriodoPedidos.todos) periodo.rotulo,
  ].join(' · ');

  bool get filtrando =>
      situacoes.isNotEmpty ||
      periodo != PeriodoPedidos.todos ||
      busca.trim().isNotEmpty;

  void alternarSituacao(SituacaoPedido situacao) {
    situacoes = {...situacoes};
    if (!situacoes.remove(situacao)) situacoes.add(situacao);
    notifyListeners();
  }

  void escolherPeriodo(PeriodoPedidos novo) {
    periodo = novo;
    notifyListeners();
  }

  void buscar(String texto) {
    busca = texto;
    notifyListeners();
  }

  void limparFiltros() {
    situacoes = {};
    periodo = PeriodoPedidos.todos;
    busca = '';
    notifyListeners();
  }

  @override
  void dispose() {
    _inscricao?.cancel();
    super.dispose();
  }
}

