  Future<void> _aoMudarUsuario(String? uid) async {
    final consulta = ++_consulta;
    try {
      final situacao = await _observarSessao.situacaoDe(uid);
      if (consulta != _consulta) return;
      _mudar(switch (situacao) {
        SituacaoSessao.deslogado => EstadoSessao.deslogado,
        SituacaoSessao.cadastroPendente => EstadoSessao.cadastroPendente,
        SituacaoSessao.cliente => EstadoSessao.cliente,
        SituacaoSessao.administrador => EstadoSessao.administrador,
      });
    } on FalhaServico catch (e) {
      if (consulta != _consulta) return;
      _mudar(EstadoSessao.falha, erro: e.mensagem);
    }
  }

